import{z as p,x as E,o as s,c as d,q as B,j as o,D as l,d as r,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Adam ε 与更新尺度","description":"","frontmatter":{"title":"Adam ε 与更新尺度","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/adam-epsilon-update-scale.md","filePath":"llm/adam-epsilon-update-scale.md","lastUpdated":1791413859000}'),A={name:"llm/adam-epsilon-update-scale.md"};function m(v,a,D,u,h,c){const t=E("Mermaid");return s(),d("div",null,[a[2]||(a[2]=B('<h1 id="adam-ε-与更新尺度" tabindex="-1">Adam ε 与更新尺度 <a class="header-anchor" href="#adam-ε-与更新尺度" aria-label="Permalink to &quot;Adam ε 与更新尺度&quot;">​</a></h1><div class="epigraph"><p>分母里的 $\\varepsilon$ 本是为了避免除零；当二阶矩本身小于 $\\varepsilon$，自适应步长不再由梯度尺度决定，而由这个常数决定。</p><footer>—— Kingma &amp; Ba, Adam, ICLR 2015；大模型中的不稳分析见 Molybog et al., A Theory on Adam Instability in Large-Scale Machine Learning, 2023</footer></div><p><a href="/llm/post-ln-warmup">上一课</a>把 LN 位置与 warmup 对齐。缺口进入 <a href="/llm/adamw">AdamW</a> 内部：更新是 \\(-\\eta\\,\\hat m/(\\sqrt{\\hat v}+\\varepsilon)\\)。主干写了解耦衰减，没有把 \\(\\varepsilon\\) 当成稳定性旋钮。Kingma 与 Ba 给的默认 \\(10^{-8}\\) 在 FP32 全连接网上几乎看不见；LLM 里大量参数的梯度长期稀疏（词表尾、偏置、某些头），\\(\\sqrt{v}\\) 可以小于 \\(\\varepsilon\\)，于是这些坐标的有效学习率变成 \\(\\eta/\\varepsilon\\)，与 μP 扫到的 \\(\\eta\\) 无关。本课写这个交叉，下一课写 \\(\\beta_2\\) 与尖峰。<span class="marginnote">「自适应学习率」就是给每个参数配一个独立油门：历史上梯度一直大的参数，分母 \\(\\sqrt{v}\\) 大、步子被压小；几乎没收到梯度的参数，分母小、步子放大——好让所有参数进度接近。\\(\\varepsilon\\) 是这套机制的&quot;地板&quot;，本课要说的正是：地板一旦比 \\(v\\) 本身还高，油门就失灵了。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(v\\) 是梯度平方的滑动平均。嵌入里罕见 token、刚被初始化的专家、以及 LN 的 \\(\\gamma\\) 在早期，都可以有 \\(g\\approx 0\\) 然后突然来一次非零 \\(g\\)。若此前 \\(v\\approx 0\\)，分母 \\(\\approx\\varepsilon\\)，一步更新幅度是 \\(|g|\\) 的 \\(\\eta/\\varepsilon\\) 倍量级（再经 \\(m\\) 平滑）。\\(\\varepsilon=10^{-8}\\)、\\(\\eta=3\\times 10^{-4}\\) 时 \\(\\eta/\\varepsilon=3\\times 10^{4}\\)，对「几乎没见过梯度的坐标」是灾难。GPT-3 175B 就把 \\(\\varepsilon\\) 整体抬到 \\(10^{-6}\\)，也有配方对嵌入单独分组给更大的 \\(\\varepsilon\\)，图的就是这个。<span class="marginnote">拿词表想一下：常用词的嵌入行几乎每个 batch 都被更新，\\(v\\) 很&quot;热&quot;；而一个 5 万词表里的生僻词，可能训练一整天只被点亮几次。这一行平时 \\(v\\approx 0\\)，突然某句话用到它，\\(\\sqrt{v}+\\varepsilon\\approx 10^{-8}\\)，一步就把这行嵌入推出去老远——下次再遇到这个词，它的表示已经面目全非。</span></p><p>混合精度下还有第二条：\\(\\sqrt{v}\\) 在 BF16 里下溢到 0，即使 FP32 主权重上 \\(v\\) 非零，若 \\(v\\) 被错误地存成低精度，\\(\\varepsilon\\) 必须大到能当护栏。Molybog 等人从理论上讨论 Adam 在大规模训练中的不稳，与「分母过小 → 偶发巨步」同方向。</p><p><span class="marginnote">有的实现把 \\(\\varepsilon\\) <strong>加在平方根里面</strong>：\\(\\sqrt{v+\\varepsilon}\\)。这改变小 \\(v\\) 时的渐近，与原论文 \\(\\sqrt{v}+\\varepsilon\\) 不是同一更新。复现必须对到代码，不能只对到「AdamW, eps=1e-8」一行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分组而不是全局拧：</p><ul><li>隐藏 GEMM：可保留 \\(10^{-8}\\)，它们的 \\(v\\) 通常够大。</li><li>嵌入 / lm_head：更大的 \\(\\varepsilon\\) 或更小的 \\(\\eta\\)，避免热 token 以外的行被 \\(\\eta/\\varepsilon\\) 抽打。</li><li>LN / RMSNorm 的 \\(\\gamma,\\beta\\)：维度极小，\\(v\\) 估计噪，常常需要更大 \\(\\varepsilon\\) 或从自适应里拿出来用 SGD 式更新（少见，但应知道选项）。</li></ul><p>coord check：在代理模型上画各层 \\(|\\Delta\\theta|/|\\theta|\\) 的中位数。若嵌入组比隐藏层大几个数量级，先查 \\(\\varepsilon\\) 与 \\(\\eta\\) 分组，再查是否忘了把嵌入从过大的全局 \\(\\eta\\) 里拆出。</p><p>不要用增大 \\(\\varepsilon\\) 去「当权重衰减」或「当 clip」：\\(\\varepsilon\\) 只在 \\(v\\) 小的坐标上起作用，对已经很热的坐标几乎恒等。持续贴顶的梯度范数应回到上一课，而不是把 \\(\\varepsilon\\) 改成 \\(10^{-3}\\) 把全体自适应关掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Adam 本意是用 \\(\\sqrt{v}\\) 当每坐标 RMS 梯度，使更新与梯度尺度无关。\\(\\varepsilon\\) 是该估计的地板。地板一旦主导，自适应消失，退化成「大学习率 SGD + 动量」，且只发生在冷坐标上——最冷的坐标一步走最远。这与直觉「稀疏该学慢」相反。权重衰减在这些坐标上若仍按 \\(\\eta\\lambda\\) 解耦乘，相对那一次巨步可以忽略，于是冷行的范数被单次更新决定。</p><p>μP 的表假设更新由正确的自适应尺度主导。\\(\\varepsilon\\) 主导时，宽度迁移失效：窄模型上所有坐标都够热，\\(\\varepsilon\\) 看不见；宽模型词表行更冷，\\(\\varepsilon\\) 突然接管。这是后课「学习率敏感度与 μP 实践」必须把 \\(\\varepsilon\\) 写进检查清单的原因。</p>',15)),(s(),o(i,null,{default:l(()=>[n(t,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOT%5B%22%E7%83%AD%E5%9D%90%E6%A0%87%EF%BC%9Av%20%E5%A4%A7%22%5D%20--%3E%20N1%5B%22sqrt(v)%20%E4%B8%BB%E5%AF%BC%E5%88%86%E6%AF%8D%22%5D%0A%20%20N1%20--%3E%20U1%5B%22%E6%AD%A5%E5%AD%90%E4%B8%8E%E6%A2%AF%E5%BA%A6%E5%B0%BA%E5%BA%A6%E6%97%A0%E5%85%B3%EF%BC%8C%E5%B9%B3%E7%A8%B3%22%5D%0A%20%20COLD%5B%22%E5%86%B7%E5%9D%90%E6%A0%87%EF%BC%9Av%20%E8%BF%91%200%22%5D%20--%3E%20N2%5B%22%CE%B5%20%E4%B8%BB%E5%AF%BC%E5%88%86%E6%AF%8D%22%5D%0A%20%20N2%20--%3E%20U2%5B%22%E6%9C%89%E6%95%88%E6%AD%A5%E9%95%BF%20%CE%B7%2F%CE%B5%EF%BC%8C%E5%81%B6%E5%8F%91%E5%B7%A8%E6%AD%A5%22%5D%0A%20%20U1%20--%3E%20OK%5B%22%E8%87%AA%E9%80%82%E5%BA%94%E4%BB%8D%E7%84%B6%E6%88%90%E7%AB%8B%22%5D%0A%20%20U2%20--%3E%20BAD%5B%22%E8%87%AA%E9%80%82%E5%BA%94%E5%A4%B1%E6%95%88%EF%BC%8C%E6%9C%80%E5%86%B7%E5%8F%8D%E8%80%8C%E8%B5%B0%E5%BE%97%E6%9C%80%E8%BF%9C%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},'常见误区：以为"小模型上试好的超参，直接搬到大模型就行"。μP 理论给了这种迁移一些依据，但它的前提是自适应分母由 \\(\\sqrt{v}\\) 主导。窄模型里没有冷到触发 \\(\\varepsilon\\) 地板的坐标，宽模型的词表尾更冷——同一组超参，窄模型上稳稳当当，放大后冷坐标被 \\(\\eta/\\varepsilon\\) 抽打。迁移前把 \\(\\varepsilon\\)、参数分组一起检查，不是迷信单点学习率。')],-1)),a[4]||(a[4]=e("h2",{id:"边界",tabindex:"-1"},[r("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=e("p",null,"本课不改 \\(\\beta_1,\\beta_2\\)；\\(\\beta_2\\) 决定 \\(v\\) 的记忆长度，下一课专门对尖峰。Adafactor、Lion、Sophia 有自己的地板与因式分解，不能把 Adam 的 \\(\\varepsilon\\) 数字贴过去。Fused Adam 的数值顺序（先加 \\(\\varepsilon\\) 再开方还是相反）属于实现，验收靠一小步对照非融合核，不要假设硬件核与论文公式逐位相同。",-1)),(s(),o(i,null,{default:l(()=>[n(t,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E6%A2%AF%E5%BA%A6%20g%22%5D%20--%3E%20V%5B%22%E4%BA%8C%E9%98%B6%E7%9F%A9%20v%22%5D%0A%20%20V%20--%3E%20DEN%5B%22sqrt(v)%20%2B%20eps%22%5D%0A%20%20DEN%20--%3E%20U%5B%22%E6%9B%B4%E6%96%B0%20eta%20m%20%2F%20%E5%88%86%E6%AF%8D%22%5D%0A%20%20EPS%5B%22eps%20%E5%9C%B0%E6%9D%BF%22%5D%20--%3E%20DEN%0A%20%20COLD%5B%22%E5%86%B7%E5%9D%90%E6%A0%87%20v%20%E8%BF%91%200%22%5D%20--%3E%20EPS%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=e("ul",null,[e("li",null,"\\(\\varepsilon\\) 是自适应分母的地板；冷坐标上有效学习率变成 \\(\\eta/\\varepsilon\\)，可远大于名义 \\(\\eta\\)。"),e("li",null,"按嵌入、LN、隐藏层分组，不要全局拧到 \\(10^{-3}\\) 关掉 Adam。"),e("li",null,"\\(\\sqrt{v}+\\varepsilon\\) 与 \\(\\sqrt{v+\\varepsilon}\\) 是不同更新；低精度存储 \\(v\\) 会让地板更早接管。"),e("li",null,"\\(\\varepsilon\\) 主导时 μP 迁移假设破裂。"),e("li",null,"出处：Kingma & Ba, ICLR 2015；Molybog et al., 2023。")],-1))])}const g=p(A,[["render",m]]);export{b as __pageData,g as default};
